"use strict";function generateBreadcrumbs(){let e=document.getElementById("breadcrumbs");if(!e)return;e.innerHTML="";let t="/mmenu",n=window.location.pathname.split("/").filter(e=>e.length>0);n=n.filter(e=>"index.php"!==e&&"mmenu"!==e);let a=document.querySelector("h1"),r=a?a.textContent:document.title,i=window.location.search?window.location.search.substring(1):null,l=t,p=document.createElement("li"),c=document.createElement("a");c.href=`${t}/mmenu.php${i&&"inactivity"!==i?`?${i}`:""}`,c.textContent="Home",p.appendChild(c);let d=document.createElement("span");d.setAttribute("aria-hidden","true"),d.setAttribute("data-symbol",">"),d.textContent=" > ",p.appendChild(d),e.appendChild(p),n.forEach((t,a)=>{let p=a===n.length-1,c=capitalizeFirstLetterOfEachWord(t.replace(/-/g," "));l+=`/${t}`;let d=document.createElement("li");if(p)d.textContent=r;else{let o=document.createElement("a");o.href=`${l}/index.php${i&&"inactivity"!==i?`?${i}`:""}`,o.textContent=c,d.appendChild(o);let h=document.createElement("span");h.setAttribute("aria-hidden","true"),h.setAttribute("data-symbol",">"),h.textContent=" > ",d.appendChild(h)}e.appendChild(d)})}function capitalizeFirstLetterOfEachWord(e){return e.replace(/\b\w/g,e=>e.toUpperCase())}window.onload=generateBreadcrumbs;